package com.teguwaz.memory;

import java.time.Instant;
import java.util.List;
import java.util.UUID;

import com.teguwaz.media.MediaKind;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

public final class MemoryDtos {

    private MemoryDtos() {
    }

    /**
     * Create or replace a memory. {@code clientId} is generated by the app when
     * the memory is recorded (possibly offline); sending the same one twice
     * returns the memory already saved instead of creating a duplicate.
     */
    public record MemoryRequest(
            UUID clientId,
            UUID tripId,
            @NotBlank @Size(max = 200) String title,
            @Size(max = 20000) String story,
            @Size(max = 200) String placeName,
            @Pattern(regexp = "^[A-Z]{2}(-[A-Z0-9]{1,3})?$", message = "must be an ISO 3166 code such as ET-AM")
            String regionCode,
            @DecimalMin("-90.0") @DecimalMax("90.0") Double latitude,
            @DecimalMin("-180.0") @DecimalMax("180.0") Double longitude,
            @NotNull Instant happenedAt,
            Privacy privacy) {
    }

    public record PrivacyRequest(@NotNull Privacy privacy) {
    }

    public record MediaResponse(
            UUID id,
            MediaKind kind,
            String contentType,
            long sizeBytes,
            int sortOrder,
            String url) {
    }

    public record MemoryResponse(
            UUID id,
            UUID clientId,
            UUID tripId,
            String title,
            String story,
            String placeName,
            String regionCode,
            Double latitude,
            Double longitude,
            Instant happenedAt,
            Privacy privacy,
            List<MediaResponse> media,
            Instant createdAt,
            Instant updatedAt) {
    }
}
